DO $$BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='salesflow_owner')THEN CREATE ROLE salesflow_owner LOGIN PASSWORD '__MIGRATION_PASSWORD__' NOINHERIT;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='salesflow_runtime')THEN CREATE ROLE salesflow_runtime LOGIN PASSWORD '__WORKFLOW_DB_PASSWORD__' NOINHERIT;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='n8n_internal')THEN CREATE ROLE n8n_internal LOGIN PASSWORD '__N8N_DB_PASSWORD__' NOINHERIT;END IF;
END$$;
GRANT CONNECT ON DATABASE salesflow TO salesflow_owner,salesflow_runtime,n8n_internal;
GRANT CREATE ON DATABASE salesflow TO n8n_internal;
GRANT USAGE,CREATE ON SCHEMA public TO n8n_internal;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS salesflow AUTHORIZATION salesflow_owner;
ALTER SCHEMA salesflow OWNER TO salesflow_owner;
SET ROLE salesflow_owner;
SET search_path=salesflow,public;

CREATE TABLE IF NOT EXISTS accounts(id text PRIMARY KEY,enabled bool NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS config_docs(account_ref text NOT NULL REFERENCES accounts(id),kind text NOT NULL,version text NOT NULL,body jsonb NOT NULL,active bool NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_ref,kind,version));
CREATE UNIQUE INDEX IF NOT EXISTS config_one_active ON config_docs(account_ref,kind)WHERE active;
CREATE TABLE IF NOT EXISTS controls(account_ref text NOT NULL REFERENCES accounts(id),key text NOT NULL,value jsonb NOT NULL,PRIMARY KEY(account_ref,key));
CREATE TABLE IF NOT EXISTS auth_tokens(hash text PRIMARY KEY,role text NOT NULL CHECK(role IN('owner','runtime','operator','scheduler')),account_ref text REFERENCES accounts(id),actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(account_ref text NOT NULL REFERENCES accounts(id),id uuid NOT NULL DEFAULT gen_random_uuid(),external_ref text NOT NULL,locale text NOT NULL DEFAULT'en',PRIMARY KEY(account_ref,id),UNIQUE(account_ref,external_ref));
CREATE TABLE IF NOT EXISTS consent_events(account_ref text NOT NULL,contact_id uuid NOT NULL,status text NOT NULL CHECK(status IN('granted','revoked')),evidence text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_ref,contact_id,occurred_at),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id));
CREATE TABLE IF NOT EXISTS conversations(account_ref text NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,lifecycle text NOT NULL DEFAULT'active',owner text NOT NULL DEFAULT'ai',version bigint NOT NULL DEFAULT 0,last_seq bigint NOT NULL DEFAULT 0,campaign bool NOT NULL DEFAULT true,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,contact_id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id));
CREATE TABLE IF NOT EXISTS inbound_messages(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL,provider_id text NOT NULL,contact_ref text NOT NULL,body text NOT NULL,body_hash text NOT NULL,received_at timestamptz NOT NULL,seq bigint NOT NULL,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,provider_id),UNIQUE(account_ref,conversation_id,seq),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id));
CREATE TABLE IF NOT EXISTS turns(account_ref text NOT NULL,inbound_id uuid NOT NULL,conversation_id uuid NOT NULL,state text NOT NULL DEFAULT'pending',claim uuid,claim_until timestamptz,attempts int NOT NULL DEFAULT 0,result jsonb,PRIMARY KEY(account_ref,inbound_id),FOREIGN KEY(account_ref,inbound_id)REFERENCES inbound_messages(account_ref,id));
CREATE TABLE IF NOT EXISTS intents(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,conversation_id uuid NOT NULL,source_id uuid NOT NULL,kind text NOT NULL,expected_version bigint NOT NULL,policy_version text NOT NULL,knowledge_version text NOT NULL,body text NOT NULL,template_key text,provenance jsonb NOT NULL,state text NOT NULL DEFAULT'pending',reason text,lease uuid,lease_until timestamptz,attempts int NOT NULL DEFAULT 0,next_attempt timestamptz,provider_id text,provider_status text,provider_time timestamptz,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,conversation_id,source_id,kind),UNIQUE(account_ref,provider_id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id));
CREATE TABLE IF NOT EXISTS intent_transitions(id bigserial PRIMARY KEY,account_ref text NOT NULL,intent_id uuid NOT NULL,from_state text,to_state text NOT NULL,reason text NOT NULL,at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(account_ref,intent_id)REFERENCES intents(account_ref,id));
CREATE TABLE IF NOT EXISTS provider_events(account_ref text NOT NULL,event_id text NOT NULL,intent_id uuid NOT NULL,provider_id text NOT NULL,status text NOT NULL CHECK(status IN('accepted','sent','delivered','read','failed')),provider_time timestamptz NOT NULL,payload_hash text NOT NULL,PRIMARY KEY(account_ref,event_id),FOREIGN KEY(account_ref,intent_id)REFERENCES intents(account_ref,id));
CREATE TABLE IF NOT EXISTS followups(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,conversation_id uuid NOT NULL,due_at timestamptz NOT NULL,expected_version bigint NOT NULL,template_key text NOT NULL DEFAULT'followup-en',state text NOT NULL DEFAULT'due',claim uuid,claim_until timestamptz,attempts int NOT NULL DEFAULT 0,next_attempt timestamptz,intent_id uuid,reason text,PRIMARY KEY(account_ref,id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id));
CREATE TABLE IF NOT EXISTS handoffs(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,conversation_id uuid NOT NULL,source_id uuid NOT NULL,reason text NOT NULL,queue text NOT NULL,deadline timestamptz NOT NULL,evidence jsonb NOT NULL,state text NOT NULL DEFAULT'pending',claim uuid,claim_until timestamptz,attempts int NOT NULL DEFAULT 0,next_attempt timestamptz,PRIMARY KEY(account_ref,id),UNIQUE(account_ref,source_id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id),FOREIGN KEY(account_ref,conversation_id)REFERENCES conversations(account_ref,id),FOREIGN KEY(account_ref,source_id)REFERENCES inbound_messages(account_ref,id));
CREATE TABLE IF NOT EXISTS deletion_requests(account_ref text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,state text NOT NULL DEFAULT'pending',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,PRIMARY KEY(account_ref,id),FOREIGN KEY(account_ref,contact_id)REFERENCES contacts(account_ref,id));
CREATE TABLE IF NOT EXISTS deletion_targets(account_ref text NOT NULL,request_id uuid NOT NULL,target_type text NOT NULL,target_id text NOT NULL,state text NOT NULL,PRIMARY KEY(account_ref,request_id,target_type,target_id),FOREIGN KEY(account_ref,request_id)REFERENCES deletion_requests(account_ref,id));
CREATE TABLE IF NOT EXISTS releases(account_ref text NOT NULL,id text NOT NULL,manifest_hash text NOT NULL,manifest jsonb NOT NULL,active bool NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_ref,id));
DROP INDEX IF EXISTS release_one_active;
CREATE TABLE IF NOT EXISTS release_pointers(account_ref text PRIMARY KEY REFERENCES accounts(id),release_id text NOT NULL,manifest_hash text NOT NULL,FOREIGN KEY(account_ref,release_id)REFERENCES releases(account_ref,id));
CREATE TABLE IF NOT EXISTS audit_events(id bigserial PRIMARY KEY,account_ref text REFERENCES accounts(id),event text NOT NULL,reason text NOT NULL,actor text NOT NULL,details jsonb NOT NULL DEFAULT'{}',at timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION immutable()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'append-only';END$$;
CREATE OR REPLACE FUNCTION provider_immutable_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='UPDATE'AND current_setting('salesflow.deletion_mode',true)='on'AND NEW.account_ref=OLD.account_ref AND NEW.event_id=OLD.event_id AND NEW.intent_id=OLD.intent_id AND NEW.status=OLD.status AND NEW.provider_time=OLD.provider_time AND NEW.provider_id LIKE'deleted-%'THEN RETURN NEW;END IF;RAISE EXCEPTION'append-only';END$$;
DROP TRIGGER IF EXISTS audit_immutable ON audit_events;CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable();
DROP TRIGGER IF EXISTS transitions_immutable ON intent_transitions;CREATE TRIGGER transitions_immutable BEFORE UPDATE OR DELETE ON intent_transitions FOR EACH ROW EXECUTE FUNCTION immutable();
DROP TRIGGER IF EXISTS provider_immutable ON provider_events;CREATE TRIGGER provider_immutable BEFORE UPDATE OR DELETE ON provider_events FOR EACH ROW EXECUTE FUNCTION provider_immutable_guard();
DROP TRIGGER IF EXISTS releases_immutable ON releases;CREATE TRIGGER releases_immutable BEFORE UPDATE OR DELETE ON releases FOR EACH ROW EXECUTE FUNCTION immutable();

CREATE OR REPLACE FUNCTION actor_for(t text,want text DEFAULT NULL)RETURNS TABLE(role text,account_ref text,actor text)LANGUAGE sql STABLE SECURITY DEFINER SET search_path=salesflow,public AS $$SELECT x.role,x.account_ref,x.actor FROM auth_tokens x LEFT JOIN accounts a ON a.id=x.account_ref WHERE x.hash=encode(digest(t,'sha256'),'hex')AND(want IS NULL OR x.role=want)AND(x.account_ref IS NULL OR a.enabled)$$;
CREATE OR REPLACE FUNCTION bootstrap(t text,r text,a text,acct text DEFAULT NULL)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$BEGIN IF session_user<>'salesflow_owner'AND session_user<>'postgres'THEN RAISE EXCEPTION'owner only';END IF;INSERT INTO auth_tokens VALUES(encode(digest(t,'sha256'),'hex'),r,acct,a)ON CONFLICT DO NOTHING;END$$;
CREATE OR REPLACE FUNCTION validate_config(k text,b jsonb)RETURNS bool LANGUAGE plpgsql IMMUTABLE AS $$BEGIN
 IF b->>'accountRef' IS NULL OR b->>'kind'<>k OR b->>'version' IS NULL THEN RETURN false;END IF;
 IF k='retry'AND NOT(b?&ARRAY['maxAttempts','backoffSeconds','leaseSeconds','turnClaimSeconds','followupClaimSeconds'])OR k='sales_policy'AND NOT(b?&ARRAY['allowedOffers','allowedClaims','minimumConfidence','frequencyCap24h','campaignEnabled','quietHoursUtc'])OR k='consent_templates'AND NOT(b?&ARRAY['optOutSignals','humanSignals','templates','serviceWindowHours'])OR k='handoff'AND NOT(b?&ARRAY['queue','deadlineSeconds','maxAttempts','backoffSeconds','claimSeconds'])OR k='model'AND NOT(b?&ARRAY['selection','productionEnabled','allowedClaims'])OR k='product_knowledge'AND NOT(b?'sources')OR k='qualification'AND NOT(b?&ARRAY['minimumScore','handoffScore'])OR k='retention'AND NOT(b?&ARRAY['auditDays','messageDays'])OR k='release_set'AND NOT(b?&ARRAY['reviewedManifestHash','policyVersion','knowledgeVersion','manifestVersion'])THEN RETURN false;END IF;
 IF k='retry'THEN RETURN(b->>'maxAttempts')::int BETWEEN 1 AND 10 AND(b->>'backoffSeconds')::int BETWEEN 1 AND 3600 AND(b->>'leaseSeconds')::int BETWEEN 1 AND 300 AND(b->>'turnClaimSeconds')::int BETWEEN 1 AND 300 AND(b->>'followupClaimSeconds')::int BETWEEN 1 AND 300;
 ELSIF k='sales_policy'THEN RETURN jsonb_typeof(b->'allowedOffers')='array'AND jsonb_array_length(b->'allowedOffers')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'allowedOffers')x WHERE jsonb_typeof(x)<>'string')AND jsonb_typeof(b->'allowedClaims')='array'AND jsonb_array_length(b->'allowedClaims')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'allowedClaims')x WHERE jsonb_typeof(x)<>'string')AND(b->>'minimumConfidence')::numeric BETWEEN 0 AND 1 AND(b->>'frequencyCap24h')::int BETWEEN 1 AND 100 AND jsonb_typeof(b->'campaignEnabled')='boolean'AND(b#>>'{quietHoursUtc,start}')::int BETWEEN 0 AND 23 AND(b#>>'{quietHoursUtc,end}')::int BETWEEN 0 AND 23;
 ELSIF k='consent_templates'THEN RETURN(b->>'serviceWindowHours')::int BETWEEN 1 AND 168 AND jsonb_typeof(b->'optOutSignals')='array'AND jsonb_array_length(b->'optOutSignals')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'optOutSignals')x WHERE jsonb_typeof(x)<>'string')AND jsonb_typeof(b->'humanSignals')='array'AND jsonb_array_length(b->'humanSignals')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'humanSignals')x WHERE jsonb_typeof(x)<>'string')AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(b->'optOutSignals')x JOIN jsonb_array_elements_text(b->'humanSignals')y ON lower(x)=lower(y))AND jsonb_typeof(b->'templates')='array'AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'templates')x WHERE jsonb_typeof(x)<>'object'OR COALESCE(x->>'key','')=''OR jsonb_typeof(x->'approved')<>'boolean'OR(x->>'windowHours')::int NOT BETWEEN 1 AND 168);
 ELSIF k='handoff'THEN RETURN COALESCE(b->>'queue','')<>''AND(b->>'deadlineSeconds')::int BETWEEN 1 AND 86400 AND(b->>'maxAttempts')::int BETWEEN 1 AND 10 AND(b->>'backoffSeconds')::int BETWEEN 1 AND 3600 AND(b->>'claimSeconds')::int BETWEEN 1 AND 300;
 ELSIF k='model'THEN RETURN b->>'selection'='synthetic-local'AND NOT(b->>'productionEnabled')::bool AND jsonb_typeof(b->'allowedClaims')='array'AND jsonb_array_length(b->'allowedClaims')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'allowedClaims')x WHERE jsonb_typeof(x)<>'string');
 ELSIF k='product_knowledge'THEN RETURN jsonb_typeof(b->'sources')='array'AND jsonb_array_length(b->'sources')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'sources')x WHERE jsonb_typeof(x)<>'object'OR COALESCE(x->>'id','')=''OR jsonb_typeof(x->'claims')<>'array'OR EXISTS(SELECT 1 FROM jsonb_array_elements(x->'claims')c WHERE jsonb_typeof(c)<>'string'));
 ELSIF k='qualification'THEN RETURN(b->>'minimumScore')::int BETWEEN 0 AND 100 AND(b->>'handoffScore')::int BETWEEN 0 AND 100 AND(b->>'minimumScore')::int<=(b->>'handoffScore')::int;
 ELSIF k='retention'THEN RETURN(b->>'auditDays')::int BETWEEN 1 AND 3650 AND(b->>'messageDays')::int BETWEEN 1 AND 3650 AND(b->>'messageDays')::int<=(b->>'auditDays')::int;
 ELSIF k='release_set'THEN RETURN COALESCE(b->>'reviewedManifestHash','')~'^[0-9a-f]{64}$'AND COALESCE(b->>'policyVersion','')<>''AND COALESCE(b->>'knowledgeVersion','')<>''AND COALESCE(b->>'manifestVersion','')<>'';
 END IF;RETURN false;EXCEPTION WHEN OTHERS THEN RETURN false;END$$;
CREATE OR REPLACE FUNCTION publish_config(t text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;acct text:=b->>'accountRef';k text:=b->>'kind';prior jsonb;existed bool;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref<>acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF NOT validate_config(k,b)THEN RETURN'{"ok":false,"reason":"invalid_config"}';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(acct||':'||k,0));SELECT body,true INTO prior,existed FROM config_docs WHERE(account_ref,kind,version)=(acct,k,b->>'version')FOR UPDATE;IF COALESCE(existed,false)AND prior<>b THEN RETURN'{"ok":false,"reason":"version_immutable"}';END IF;IF COALESCE(existed,false)AND EXISTS(SELECT 1 FROM config_docs WHERE(account_ref,kind,version,active)=(acct,k,b->>'version',true))THEN RETURN'{"ok":true,"created":false}';END IF;UPDATE config_docs SET active=false WHERE account_ref=acct AND kind=k AND active;IF COALESCE(existed,false)THEN UPDATE config_docs SET active=true WHERE(account_ref,kind,version)=(acct,k,b->>'version');ELSE INSERT INTO config_docs VALUES(acct,k,b->>'version',b,true);END IF;INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'config_published',k,a.actor,jsonb_build_object('version',b->>'version'));RETURN'{"ok":true,"created":true}';END$$;
CREATE OR REPLACE FUNCTION set_control(t text,acct text,k text,v jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR a.account_ref<>acct OR k NOT IN('stop')THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF jsonb_typeof(v->'enabled')<>'boolean'THEN RETURN'{"ok":false,"reason":"invalid_control"}';END IF;INSERT INTO controls VALUES(acct,k,v)ON CONFLICT(account_ref,key)DO UPDATE SET value=EXCLUDED.value;INSERT INTO audit_events(account_ref,event,reason,actor)VALUES(acct,'control_changed',k,a.actor);RETURN'{"ok":true}';END$$;
CREATE OR REPLACE FUNCTION set_consent(t text,acct text,c uuid,s text,e text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR a.account_ref<>acct THEN RETURN'{"ok":false,"reason":"unauthorized"}';END IF;IF s NOT IN('granted','revoked')OR COALESCE(trim(e),'')=''OR NOT EXISTS(SELECT 1 FROM contacts WHERE(account_ref,id)=(acct,c))THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;INSERT INTO consent_events VALUES(acct,c,s,e,now());RETURN'{"ok":true}';END$$;

CREATE OR REPLACE FUNCTION ingest(t text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;c contacts;v conversations;m inbound_messages;e inbound_messages;received timestamptz;h text;cfg jsonb;norm text;BEGIN
 SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND THEN RETURN'{"ok":false,"accepted":false,"reason":"unauthorized"}';END IF;
 IF p->>'account_ref'<>a.account_ref THEN RETURN'{"ok":false,"accepted":false,"reason":"wrong_account"}';END IF;
 BEGIN received:=COALESCE((p->>'received_at')::timestamptz,now());EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"accepted":false,"reason":"invalid"}';END;
 IF COALESCE(p->>'provider_id','')=''OR COALESCE(p->>'contact_ref','')=''OR COALESCE(p->>'body','')=''OR octet_length(p->>'body')>8192 OR received>now()+interval'5 min'THEN RETURN'{"ok":false,"accepted":false,"reason":"invalid"}';END IF;
 h:=encode(digest(p->>'body','sha256'),'hex');SELECT*INTO e FROM inbound_messages WHERE account_ref=a.account_ref AND provider_id=p->>'provider_id';IF FOUND THEN IF e.body_hash<>h OR e.contact_ref<>p->>'contact_ref'THEN RETURN'{"ok":false,"accepted":false,"reason":"idempotency_conflict"}';END IF;RETURN jsonb_build_object('ok',true,'accepted',true,'created',false,'terminal','duplicate','account_ref',a.account_ref);END IF;
 SELECT body INTO cfg FROM config_docs WHERE account_ref=a.account_ref AND kind='consent_templates'AND active;IF cfg IS NULL THEN RETURN'{"ok":false,"accepted":false,"reason":"missing_config"}';END IF;norm:=lower(trim(regexp_replace(p->>'body','\s+',' ','g')));IF NOT(cfg->'optOutSignals'?norm)AND cfg->'humanSignals'?norm AND NOT EXISTS(SELECT 1 FROM config_docs WHERE account_ref=a.account_ref AND kind='handoff'AND active)THEN RETURN'{"ok":false,"accepted":false,"reason":"missing_handoff_config"}';END IF;
 INSERT INTO contacts(account_ref,external_ref)VALUES(a.account_ref,p->>'contact_ref')ON CONFLICT(account_ref,external_ref)DO UPDATE SET locale=contacts.locale RETURNING*INTO c;
 INSERT INTO conversations(account_ref,contact_id)VALUES(a.account_ref,c.id)ON CONFLICT(account_ref,contact_id)DO UPDATE SET version=conversations.version RETURNING*INTO v;PERFORM pg_advisory_xact_lock(hashtextextended(v.id::text,0));UPDATE conversations SET last_seq=last_seq+1,version=version+1 WHERE(account_ref,id)=(a.account_ref,v.id)RETURNING*INTO v;
 INSERT INTO inbound_messages(account_ref,conversation_id,provider_id,contact_ref,body,body_hash,received_at,seq)VALUES(a.account_ref,v.id,p->>'provider_id',p->>'contact_ref',p->>'body',h,received,v.last_seq)RETURNING*INTO m;INSERT INTO turns(account_ref,inbound_id,conversation_id)VALUES(a.account_ref,m.id,v.id);
 IF cfg->'optOutSignals'?norm THEN UPDATE conversations SET lifecycle='opted_out'WHERE(account_ref,id)=(a.account_ref,v.id);UPDATE intents SET state='suppressed',reason='opted_out',lease=NULL,lease_until=NULL WHERE account_ref=a.account_ref AND conversation_id=v.id AND state IN('pending','leased');UPDATE followups SET state='suppressed',reason='opted_out',claim=NULL,claim_until=NULL WHERE account_ref=a.account_ref AND conversation_id=v.id AND state IN('due','claimed','retry');UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE account_ref=a.account_ref AND conversation_id=v.id AND state IN('pending','claimed');ELSIF cfg->'humanSignals'?norm THEN UPDATE conversations SET owner='human'WHERE(account_ref,id)=(a.account_ref,v.id);SELECT body INTO cfg FROM config_docs WHERE account_ref=a.account_ref AND kind='handoff'AND active;INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence)VALUES(a.account_ref,c.id,v.id,m.id,'human_requested',cfg->>'queue',now()+make_interval(secs=>(cfg->>'deadlineSeconds')::int),jsonb_build_object('inbound_id',m.id));END IF;
 INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(a.account_ref,'ingress','accepted',a.actor,jsonb_build_object('inbound_id',m.id));RETURN jsonb_build_object('ok',true,'accepted',true,'created',true,'account_ref',a.account_ref,'conversation_id',v.id,'contact_id',c.id,'inbound_id',m.id);
EXCEPTION WHEN unique_violation THEN SELECT*INTO e FROM inbound_messages WHERE account_ref=a.account_ref AND provider_id=p->>'provider_id';IF FOUND AND e.body_hash=h AND e.contact_ref=p->>'contact_ref'THEN RETURN jsonb_build_object('ok',true,'accepted',true,'created',false,'terminal','concurrent_replay','account_ref',a.account_ref);END IF;RETURN'{"ok":false,"accepted":false,"reason":"idempotency_conflict"}';END$$;

CREATE OR REPLACE FUNCTION complete_turn(t text,acct text,conv uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;v conversations;m inbound_messages;pol jsonb;know jsonb;model jsonb;qual jsonb;handoff jsonb;i intents;retry jsonb;h uuid;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR a.account_ref<>acct THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,conv)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;SELECT im.*INTO m FROM inbound_messages im JOIN turns tr ON(tr.account_ref,tr.inbound_id)=(im.account_ref,im.id)WHERE im.account_ref=acct AND im.conversation_id=conv AND(tr.state='pending'OR(tr.state='claimed'AND tr.claim_until<=now()))ORDER BY im.seq LIMIT 1 FOR UPDATE OF tr SKIP LOCKED;IF NOT FOUND THEN RETURN'{"ok":true,"terminal":"nothing"}';END IF;SELECT body INTO retry FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF retry IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_retry"}';END IF;UPDATE turns SET state='claimed',claim=gen_random_uuid(),claim_until=now()+make_interval(secs=>(retry->>'turnClaimSeconds')::int),attempts=attempts+1 WHERE(account_ref,inbound_id)=(acct,m.id);IF v.lifecycle<>'active'OR v.owner<>'ai'THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','suppressed','reason',CASE WHEN v.lifecycle<>'active'THEN v.lifecycle ELSE'human_owned'END);END IF;SELECT body INTO pol FROM config_docs WHERE account_ref=acct AND kind='sales_policy'AND active;SELECT body INTO know FROM config_docs WHERE account_ref=acct AND kind='product_knowledge'AND active;SELECT body INTO model FROM config_docs WHERE account_ref=acct AND kind='model'AND active;SELECT body INTO qual FROM config_docs WHERE account_ref=acct AND kind='qualification'AND active;IF pol IS NULL OR know IS NULL OR model IS NULL OR qual IS NULL OR model->>'selection'<>'synthetic-local'OR NOT(model->'allowedClaims'?'service-count')OR NOT(pol->'allowedClaims'?'service-count')OR 1<(qual->>'minimumScore')::int OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(know->'sources')s WHERE s->>'id'='source-1'AND s->'claims'?'service-count')THEN SELECT body INTO handoff FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;IF handoff IS NULL THEN UPDATE turns SET state='pending',claim=NULL,claim_until=NULL WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"denied","reason":"missing_handoff_config"}';END IF;UPDATE conversations SET owner='human'WHERE(account_ref,id)=(acct,conv);INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence)VALUES(acct,v.contact_id,v.id,m.id,'grounding_invalid',handoff->>'queue',now()+make_interval(secs=>(handoff->>'deadlineSeconds')::int),jsonb_build_object('inbound_id',m.id,'qualificationVersion',qual->>'version'))ON CONFLICT(account_ref,source_id)DO UPDATE SET reason=handoffs.reason RETURNING id INTO h;UPDATE turns SET state='completed',claim=NULL,claim_until=NULL,result=jsonb_build_object('handoff_id',h)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','handoff','reason','grounding_invalid','work_id',h);END IF;INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,provenance)VALUES(acct,v.contact_id,v.id,m.id,'reply',v.version,pol->>'version',know->>'version','Synthetic Plan includes one service.',jsonb_build_object('sourceIds',jsonb_build_array('source-1'),'offerId','offer-1','claims',jsonb_build_array('service-count'),'confidence',1.0,'qualificationVersion',qual->>'version','qualificationScore',1))ON CONFLICT(account_ref,conversation_id,source_id,kind)DO UPDATE SET body=intents.body RETURNING*INTO i;UPDATE turns SET state='completed',claim=NULL,claim_until=NULL,result=jsonb_build_object('intent_id',i.id)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','created','work_id',i.id);END$$;

CREATE OR REPLACE FUNCTION authorization_reason(acct text,i intents,n timestamptz DEFAULT now())RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE v conversations;cons text;pol jsonb;retry jsonb;ct jsonb;stop bool;hr int;freq int;last_inbound timestamptz;template_hours int;BEGIN IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN RETURN'account_disabled';END IF;SELECT(value->>'enabled')::bool INTO stop FROM controls WHERE account_ref=acct AND key='stop';SELECT body INTO retry FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF stop IS NULL THEN RETURN'missing_control';ELSIF retry IS NULL THEN RETURN'missing_retry';END IF;SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,i.conversation_id);SELECT status INTO cons FROM consent_events WHERE(account_ref,contact_id)=(acct,i.contact_id)ORDER BY occurred_at DESC LIMIT 1;IF stop THEN RETURN'global_stop';ELSIF v.lifecycle<>'active'THEN RETURN v.lifecycle;ELSIF cons IS DISTINCT FROM'granted'THEN RETURN'consent_missing';ELSIF v.owner<>'ai'AND i.kind<>'handoff_ack'THEN RETURN'human_owned';ELSIF v.version<>i.expected_version THEN RETURN'stale_version';END IF;SELECT body INTO pol FROM config_docs WHERE account_ref=acct AND kind='sales_policy'AND active AND version=i.policy_version;IF pol IS NULL THEN RETURN'policy_invalid';END IF;IF NOT EXISTS(SELECT 1 FROM config_docs WHERE account_ref=acct AND kind='product_knowledge'AND active AND version=i.knowledge_version)THEN RETURN'knowledge_invalid';END IF;IF NOT(pol->'allowedOffers'?COALESCE(i.provenance->>'offerId',''))THEN RETURN'offer_invalid';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(i.provenance->'claims')c WHERE NOT(pol->'allowedClaims'?c))THEN RETURN'claim_invalid';END IF;IF COALESCE((i.provenance->>'confidence')::numeric,0)<(pol->>'minimumConfidence')::numeric THEN RETURN'confidence_low';END IF;SELECT body INTO ct FROM config_docs WHERE account_ref=acct AND kind='consent_templates'AND active;IF ct IS NULL THEN RETURN'missing_consent_config';END IF;IF i.template_key IS NOT NULL THEN SELECT(x->>'windowHours')::int INTO template_hours FROM jsonb_array_elements(ct->'templates')x WHERE x->>'key'=i.template_key AND(x->>'approved')::bool;IF template_hours IS NULL THEN RETURN'template_invalid';END IF;END IF;SELECT max(received_at)INTO last_inbound FROM inbound_messages WHERE account_ref=acct AND conversation_id=i.conversation_id;IF i.template_key IS NULL AND(last_inbound IS NULL OR last_inbound<n-make_interval(hours=>(ct->>'serviceWindowHours')::int))THEN RETURN'service_window_closed';ELSIF i.template_key IS NOT NULL AND(last_inbound IS NULL OR last_inbound<n-make_interval(hours=>template_hours))THEN RETURN'template_window_closed';END IF;hr:=extract(hour from n AT TIME ZONE'UTC');IF(pol#>>'{quietHoursUtc,start}')::int<>(pol#>>'{quietHoursUtc,end}')::int AND(((pol#>>'{quietHoursUtc,start}')::int<(pol#>>'{quietHoursUtc,end}')::int AND hr>=(pol#>>'{quietHoursUtc,start}')::int AND hr<(pol#>>'{quietHoursUtc,end}')::int)OR((pol#>>'{quietHoursUtc,start}')::int>(pol#>>'{quietHoursUtc,end}')::int AND(hr>=(pol#>>'{quietHoursUtc,start}')::int OR hr<(pol#>>'{quietHoursUtc,end}')::int)))THEN RETURN'quiet_hours';END IF;SELECT count(*)INTO freq FROM intents WHERE account_ref=acct AND contact_id=i.contact_id AND state='sent'AND provider_time>n-interval'24h';IF freq>=(pol->>'frequencyCap24h')::int THEN RETURN'frequency_cap';END IF;IF NOT v.campaign OR NOT(pol->>'campaignEnabled')::bool THEN RETURN'campaign_disabled';END IF;RETURN'authorized';END$$;

CREATE OR REPLACE FUNCTION claim_dispatch(t text,acct text,work uuid,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;r text;cfg jsonb;old text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;IF acct IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_account"}';END IF;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF cfg IS NULL THEN r:='missing_retry';ELSIF i.state='leased'AND i.lease_until>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"already_leased"}';ELSIF i.state NOT IN('pending','leased')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','not_pending','state',i.state);ELSIF i.attempts>=(cfg->>'maxAttempts')::int THEN r:='retry_exhausted';ELSIF i.next_attempt>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"backoff"}';ELSE r:=authorization_reason(acct,i,n);END IF;IF r<>'authorized'THEN old:=i.state;UPDATE intents SET state='suppressed',reason=r,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,i.id);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,'suppressed',r);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'authorization_denied',r,a.actor,jsonb_build_object('intent_id',i.id));RETURN jsonb_build_object('ok',false,'terminal','denied','reason',r);END IF;old:=i.state;UPDATE intents SET state='leased',lease=gen_random_uuid(),lease_until=n+make_interval(secs=>(cfg->>'leaseSeconds')::int),attempts=attempts+1 WHERE(account_ref,id)=(acct,i.id)RETURNING*INTO i;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,i.id,old,'leased','authorized');RETURN jsonb_build_object('ok',true,'terminal','claimed','account_ref',acct,'work_id',i.id,'lease',i.lease);END$$;
CREATE OR REPLACE FUNCTION recheck_dispatch(t text,acct text,work uuid,l uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;r text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR(a.role='runtime'AND a.account_ref<>acct)OR a.role NOT IN('runtime','scheduler')THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND OR i.state<>'leased'OR i.lease<>l OR i.lease_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"lease_mismatch"}';END IF;r:=authorization_reason(acct,i);IF r<>'authorized'THEN UPDATE intents SET state='suppressed',reason=r,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,'leased','suppressed',r);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'authorization_denied',r,a.actor,jsonb_build_object('intent_id',work,'phase','recheck'));RETURN jsonb_build_object('ok',false,'terminal','denied','reason',r);END IF;RETURN'{"ok":true,"terminal":"authorized"}';END$$;
CREATE OR REPLACE FUNCTION finish_dispatch(t text,acct text,work uuid,l uuid,outcome text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;cfg jsonb;r text;old text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR(a.role='runtime'AND a.account_ref<>acct)OR a.role NOT IN('runtime','scheduler')THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO i FROM intents WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND OR i.state<>'leased'OR i.lease<>l OR i.lease_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"lease_mismatch"}';END IF;IF outcome NOT IN('success','retryable','ambiguous','failed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_outcome"}';END IF;r:=authorization_reason(acct,i);IF r<>'authorized'THEN UPDATE intents SET state='suppressed',reason=r,lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work);INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,'leased','suppressed',r);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',r);END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;old:=i.state;IF outcome='success'THEN UPDATE intents SET state='sent',provider_id='synthetic-'||id,provider_status='accepted',provider_time=now(),lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;ELSIF outcome='retryable'AND i.attempts<(cfg->>'maxAttempts')::int THEN UPDATE intents SET state='pending',reason='provider_retryable',next_attempt=now()+make_interval(secs=>(cfg->>'backoffSeconds')::int),lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;ELSIF outcome='ambiguous'THEN UPDATE intents SET state='reconciliation_required',reason='ambiguous',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;ELSE UPDATE intents SET state='suppressed',reason='retry_exhausted',lease=NULL,lease_until=NULL WHERE(account_ref,id)=(acct,work)RETURNING*INTO i;END IF;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES(acct,work,old,i.state,COALESCE(i.reason,'success'));RETURN jsonb_build_object('ok',true,'terminal',i.state,'provider_id',i.provider_id,'next_attempt',i.next_attempt);END$$;

CREATE OR REPLACE FUNCTION callback(t text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;e provider_events;pt timestamptz;h text;rank_old int;rank_new int;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR p->>'account_ref'<>a.account_ref THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;IF COALESCE(p->>'event_id','')=''OR COALESCE(p->>'provider_id','')=''OR COALESCE(p->>'status','')NOT IN('accepted','sent','delivered','read','failed')THEN RETURN'{"ok":false,"reason":"invalid"}';END IF;BEGIN pt:=(p->>'provider_time')::timestamptz;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid"}';END;IF pt>now()+interval'5 min'THEN RETURN'{"ok":false,"reason":"future"}';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(a.account_ref||':'||(p->>'event_id'),0));SELECT*INTO i FROM intents x JOIN conversations v ON(v.account_ref,v.id)=(x.account_ref,x.conversation_id)WHERE(x.account_ref,x.provider_id)=(a.account_ref,p->>'provider_id')AND v.lifecycle<>'deleted'FOR UPDATE OF x;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"provider_mismatch"}';END IF;h:=encode(digest(p::text,'sha256'),'hex');SELECT*INTO e FROM provider_events WHERE(account_ref,event_id)=(a.account_ref,p->>'event_id');IF FOUND THEN RETURN CASE WHEN e.payload_hash=h THEN jsonb_build_object('ok',true,'created',false,'status',i.provider_status)ELSE'{"ok":false,"reason":"idempotency_conflict"}'::jsonb END;END IF;INSERT INTO provider_events VALUES(a.account_ref,p->>'event_id',i.id,p->>'provider_id',p->>'status',pt,h);rank_old:=array_position(ARRAY['accepted','sent','delivered','read'],i.provider_status);rank_new:=array_position(ARRAY['accepted','sent','delivered','read'],p->>'status');IF (p->>'status'='failed'AND COALESCE(rank_old,0)<3 AND(i.provider_time IS NULL OR pt>=i.provider_time))OR(p->>'status'<>'failed'AND(i.provider_time IS NULL OR(pt>=i.provider_time AND rank_new>=COALESCE(rank_old,0))))THEN UPDATE intents SET provider_status=p->>'status',provider_time=pt WHERE(account_ref,id)=(a.account_ref,i.id)RETURNING*INTO i;END IF;RETURN jsonb_build_object('ok',true,'created',true,'status',i.provider_status);END$$;

CREATE OR REPLACE FUNCTION schedule_followups(t text,n timestamptz DEFAULT now())RETURNS TABLE(account_ref text,work_id uuid)LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$#variable_conflict use_column
DECLARE a record;f followups;pol config_docs;know config_docs;retry jsonb;i intents;BEGIN SELECT*INTO a FROM actor_for(t,'scheduler');IF NOT FOUND THEN RETURN;END IF;FOR f IN SELECT*FROM followups WHERE(state='due'OR(state='claimed'AND claim_until<=n)OR(state='retry'AND next_attempt<=n))AND due_at<=n ORDER BY due_at FOR UPDATE SKIP LOCKED LOOP SELECT body INTO retry FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='retry'AND active;IF retry IS NULL OR f.attempts>=COALESCE((retry->>'maxAttempts')::int,0)THEN UPDATE followups x SET state='suppressed',reason=CASE WHEN retry IS NULL THEN'missing_retry'ELSE'retry_exhausted'END WHERE(x.account_ref,x.id)=(f.account_ref,f.id);CONTINUE;END IF;UPDATE followups x SET state='claimed',claim=gen_random_uuid(),claim_until=n+make_interval(secs=>(retry->>'followupClaimSeconds')::int),attempts=attempts+1 WHERE(x.account_ref,x.id)=(f.account_ref,f.id);SELECT*INTO pol FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='sales_policy'AND active;SELECT*INTO know FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='product_knowledge'AND active;IF pol.version IS NULL OR know.version IS NULL THEN UPDATE followups x SET state='retry',reason='missing_config',next_attempt=n+make_interval(secs=>(retry->>'backoffSeconds')::int),claim=NULL,claim_until=NULL WHERE(x.account_ref,x.id)=(f.account_ref,f.id);CONTINUE;END IF;INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,template_key,provenance)VALUES(f.account_ref,f.contact_id,f.conversation_id,f.id,'followup',f.expected_version,pol.version,know.version,'Synthetic follow-up.',f.template_key,'{"sourceIds":["source-1"],"offerId":"offer-1","claims":["service-count"],"confidence":1.0}')ON CONFLICT(account_ref,conversation_id,source_id,kind)DO UPDATE SET body=intents.body RETURNING*INTO i;UPDATE followups x SET state='intent_created',intent_id=i.id,claim=NULL,claim_until=NULL WHERE(x.account_ref,x.id)=(f.account_ref,f.id);account_ref:=f.account_ref;work_id:=i.id;RETURN NEXT;END LOOP;END$$;

CREATE OR REPLACE FUNCTION claim_handoff(t text,acct text,work uuid,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;h handoffs;cfg jsonb;v conversations;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR(acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF v.lifecycle='opted_out'THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN'{"ok":false,"terminal":"denied","reason":"opted_out"}';ELSIF cfg IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_config"}';ELSIF h.state IN('acknowledged','suppressed')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','terminal_state','state',h.state);ELSIF h.state='claimed'AND h.claim_until>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"already_claimed"}';ELSIF h.state NOT IN('pending','claimed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_state"}';ELSIF h.attempts>=(cfg->>'maxAttempts')::int THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN'{"ok":false,"terminal":"denied","reason":"retry_exhausted"}';ELSIF h.next_attempt>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"backoff"}';END IF;UPDATE handoffs SET state='claimed',claim=gen_random_uuid(),claim_until=n+make_interval(secs=>(cfg->>'claimSeconds')::int),attempts=attempts+1 WHERE(account_ref,id)=(acct,work)RETURNING*INTO h;RETURN jsonb_build_object('ok',true,'terminal','claimed','account_ref',acct,'work_id',h.id,'claim',h.claim,'queue',h.queue,'deadline',h.deadline);END$$;
CREATE OR REPLACE FUNCTION finish_handoff(t text,acct text,work uuid,c uuid,outcome text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;h handoffs;cfg jsonb;life text;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR a.account_ref<>acct THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND OR h.state<>'claimed'OR h.claim<>c OR h.claim_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"claim_mismatch"}';END IF;IF outcome NOT IN('success','retryable','failed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_outcome"}';END IF;SELECT lifecycle INTO life FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF life='opted_out'THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN'{"ok":false,"terminal":"denied","reason":"opted_out"}';END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;IF cfg IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_config"}';ELSIF outcome='success'THEN UPDATE handoffs SET state='acknowledged',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);ELSIF outcome='retryable'AND h.attempts<(cfg->>'maxAttempts')::int THEN UPDATE handoffs SET state='pending',next_attempt=now()+make_interval(secs=>(cfg->>'backoffSeconds')::int),claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);ELSE UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);END IF;RETURN(SELECT jsonb_build_object('ok',true,'terminal',state,'next_attempt',next_attempt)FROM handoffs WHERE(account_ref,id)=(acct,work));END$$;

CREATE OR REPLACE FUNCTION operations(t text,acct text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;c uuid;r uuid;n int;mh text;ret jsonb;rs jsonb;BEGIN SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR(acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;IF jsonb_typeof(p)<>'object'OR COALESCE(p->>'action','')=''THEN RETURN'{"ok":false,"reason":"invalid_input"}';ELSIF p->>'action'='evidence'THEN SELECT body INTO ret FROM config_docs WHERE account_ref=acct AND kind='retention'AND active;IF ret IS NULL THEN RETURN'{"ok":false,"reason":"missing_retention"}';END IF;RETURN jsonb_build_object('ok',true,'terminal','evidence','account_ref',acct,'events',(SELECT count(*)FROM audit_events WHERE account_ref=acct),'retentionVersion',ret->>'version','auditDays',(ret->>'auditDays')::int,'messageDays',(ret->>'messageDays')::int);ELSIF p->>'action'='delete'THEN BEGIN c:=(p->>'contact_id')::uuid;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid_input"}';END;IF NOT EXISTS(SELECT 1 FROM contacts WHERE(account_ref,id)=(acct,c))THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;INSERT INTO deletion_requests(account_ref,contact_id)VALUES(acct,c)RETURNING id INTO r;INSERT INTO deletion_targets SELECT acct,r,'inbound_message',id::text,'pending'FROM inbound_messages WHERE account_ref=acct AND conversation_id IN(SELECT id FROM conversations WHERE account_ref=acct AND contact_id=c)UNION ALL SELECT acct,r,'intent',id::text,'pending'FROM intents WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'followup',id::text,'pending'FROM followups WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'handoff',id::text,'pending'FROM handoffs WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'contact',c::text,'pending';PERFORM set_config('salesflow.deletion_mode','on',true);UPDATE provider_events e SET provider_id='deleted-'||e.intent_id::text,payload_hash=encode(digest('[deleted]','sha256'),'hex')WHERE e.account_ref=acct AND e.intent_id IN(SELECT id FROM intents WHERE account_ref=acct AND contact_id=c);UPDATE conversations SET lifecycle='deleted'WHERE(account_ref,contact_id)=(acct,c);UPDATE intents SET state='suppressed',reason='deleted',body='[deleted]',provenance='{}',provider_id=CASE WHEN provider_id IS NULL THEN NULL ELSE'deleted-'||id::text END,lease=NULL,lease_until=NULL WHERE account_ref=acct AND contact_id=c;UPDATE handoffs SET state='suppressed',evidence='{}',claim=NULL,claim_until=NULL WHERE account_ref=acct AND contact_id=c;UPDATE followups SET state='suppressed',reason='deleted',claim=NULL,claim_until=NULL WHERE account_ref=acct AND contact_id=c;UPDATE inbound_messages SET body='[deleted]',body_hash=encode(digest('[deleted]','sha256'),'hex'),contact_ref='[deleted]'WHERE account_ref=acct AND conversation_id IN(SELECT id FROM conversations WHERE account_ref=acct AND contact_id=c);UPDATE contacts SET external_ref='deleted-'||id::text WHERE(account_ref,id)=(acct,c);UPDATE deletion_targets SET state='completed'WHERE(account_ref,request_id)=(acct,r);UPDATE deletion_requests SET state='completed',completed_at=now()WHERE(account_ref,id)=(acct,r);SELECT count(*)INTO n FROM deletion_targets WHERE(account_ref,request_id)=(acct,r);RETURN jsonb_build_object('ok',true,'terminal','deleted','request_id',r,'targets',n,'completed',true);ELSIF p->>'action'='release'THEN IF COALESCE(p->>'release_id','')=''OR jsonb_typeof(p->'manifest')<>'object'OR COALESCE(p->>'manifest_hash','')!~'^[0-9a-f]{64}$'THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;mh:=encode(digest((p->'manifest')::text,'sha256'),'hex');SELECT body INTO rs FROM config_docs WHERE account_ref=acct AND kind='release_set'AND active;IF mh<>p->>'manifest_hash'OR rs IS NULL OR rs->>'reviewedManifestHash'<>mh OR rs->>'manifestVersion'<>p#>>'{manifest,version}'OR rs->>'policyVersion'<>p#>>'{manifest,policyVersion}'OR rs->>'knowledgeVersion'<>p#>>'{manifest,knowledgeVersion}'THEN RETURN'{"ok":false,"reason":"manifest_mismatch"}';END IF;IF EXISTS(SELECT 1 FROM releases WHERE(account_ref,id)=(acct,p->>'release_id'))THEN RETURN'{"ok":false,"reason":"release_exists"}';END IF;INSERT INTO releases VALUES(acct,p->>'release_id',mh,p->'manifest',true);INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'release_activated',p->>'release_id',a.actor,jsonb_build_object('manifest_hash',mh));RETURN jsonb_build_object('ok',true,'terminal','released','previous_release',(SELECT id FROM releases WHERE account_ref=acct AND id<>p->>'release_id'ORDER BY created_at DESC LIMIT 1));END IF;RETURN'{"ok":false,"reason":"invalid_action"}';EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'reason','invalid_input');END$$;

-- Loop-5 worker/recheck commands keep discovery and final authorization in PostgreSQL.
CREATE OR REPLACE FUNCTION complete_turn(t text,acct text,conv uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;v conversations;m inbound_messages;pol jsonb;know jsonb;model jsonb;qual jsonb;handoff jsonb;i intents;retry jsonb;h uuid;qscore int;grounded bool;
BEGIN
 SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR a.account_ref<>acct THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;
 SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,conv)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;
 SELECT im.*INTO m FROM inbound_messages im JOIN turns tr ON(tr.account_ref,tr.inbound_id)=(im.account_ref,im.id)WHERE im.account_ref=acct AND im.conversation_id=conv AND(tr.state='pending'OR(tr.state='claimed'AND tr.claim_until<=now()))ORDER BY im.seq LIMIT 1 FOR UPDATE OF tr SKIP LOCKED;IF NOT FOUND THEN RETURN'{"ok":true,"terminal":"nothing"}';END IF;
 SELECT body INTO retry FROM config_docs WHERE account_ref=acct AND kind='retry'AND active;IF retry IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_retry"}';END IF;
 IF(SELECT attempts FROM turns WHERE(account_ref,inbound_id)=(acct,m.id))>=(retry->>'maxAttempts')::int THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL,result='{"reason":"retry_exhausted"}'WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"suppressed","reason":"retry_exhausted"}';END IF;
 UPDATE turns SET state='claimed',claim=gen_random_uuid(),claim_until=now()+make_interval(secs=>(retry->>'turnClaimSeconds')::int),attempts=attempts+1 WHERE(account_ref,inbound_id)=(acct,m.id);
 IF v.lifecycle='active'AND v.owner='human'THEN SELECT id INTO h FROM handoffs WHERE(account_ref,source_id)=(acct,m.id)AND state='pending';IF h IS NOT NULL THEN UPDATE turns SET state='completed',claim=NULL,claim_until=NULL,result=jsonb_build_object('handoff_id',h)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','handoff','reason','human_requested','work_id',h,'work_type','handoff');END IF;END IF;
 IF v.lifecycle<>'active'OR v.owner<>'ai'THEN UPDATE turns SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','suppressed','reason',CASE WHEN v.lifecycle<>'active'THEN v.lifecycle ELSE'human_owned'END);END IF;
 SELECT body INTO pol FROM config_docs WHERE account_ref=acct AND kind='sales_policy'AND active;SELECT body INTO know FROM config_docs WHERE account_ref=acct AND kind='product_knowledge'AND active;SELECT body INTO model FROM config_docs WHERE account_ref=acct AND kind='model'AND active;SELECT body INTO qual FROM config_docs WHERE account_ref=acct AND kind='qualification'AND active;
 qscore:=CASE WHEN lower(m.body)LIKE'%qualified%'THEN COALESCE((qual->>'handoffScore')::int,101)ELSE COALESCE((qual->>'minimumScore')::int,101)END;
 grounded:=pol IS NOT NULL AND know IS NOT NULL AND model IS NOT NULL AND qual IS NOT NULL AND model->>'selection'='synthetic-local'AND model->'allowedClaims'?'service-count'AND pol->'allowedClaims'?'service-count'AND qscore>=(qual->>'minimumScore')::int AND EXISTS(SELECT 1 FROM jsonb_array_elements(know->'sources')s WHERE s->>'id'='source-1'AND s->'claims'?'service-count');
 IF NOT grounded OR qscore>=(qual->>'handoffScore')::int THEN
  SELECT body INTO handoff FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;IF handoff IS NULL THEN UPDATE turns SET state='pending',claim=NULL,claim_until=NULL WHERE(account_ref,inbound_id)=(acct,m.id);RETURN'{"ok":false,"terminal":"denied","reason":"missing_handoff_config"}';END IF;
  UPDATE conversations SET owner='human'WHERE(account_ref,id)=(acct,conv);INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence)VALUES(acct,v.contact_id,v.id,m.id,CASE WHEN grounded THEN'qualification_threshold'ELSE'grounding_invalid'END,handoff->>'queue',now()+make_interval(secs=>(handoff->>'deadlineSeconds')::int),jsonb_build_object('inbound_id',m.id,'qualificationVersion',qual->>'version','qualificationScore',qscore,'handoffScore',qual->>'handoffScore'))ON CONFLICT(account_ref,source_id)DO UPDATE SET reason=handoffs.reason RETURNING id INTO h;UPDATE turns SET state='completed',claim=NULL,claim_until=NULL,result=jsonb_build_object('handoff_id',h)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','handoff','reason',CASE WHEN grounded THEN'qualification_threshold'ELSE'grounding_invalid'END,'work_id',h,'work_type','handoff');
 END IF;
 INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,provenance)VALUES(acct,v.contact_id,v.id,m.id,'reply',v.version,pol->>'version',know->>'version','Synthetic Plan includes one service.',jsonb_build_object('sourceIds',jsonb_build_array('source-1'),'offerId','offer-1','claims',jsonb_build_array('service-count'),'confidence',1.0,'qualificationVersion',qual->>'version','qualificationScore',qscore,'handoffScore',qual->>'handoffScore'))ON CONFLICT(account_ref,conversation_id,source_id,kind)DO UPDATE SET body=intents.body RETURNING*INTO i;
 UPDATE turns SET state='completed',claim=NULL,claim_until=NULL,result=jsonb_build_object('intent_id',i.id)WHERE(account_ref,inbound_id)=(acct,m.id);RETURN jsonb_build_object('ok',true,'terminal','created','work_id',i.id,'work_type','dispatch');
END$$;

CREATE OR REPLACE FUNCTION schedule_followups(t text,n timestamptz DEFAULT now())RETURNS TABLE(account_ref text,work_id uuid)LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$#variable_conflict use_column
DECLARE a record;f followups;pol config_docs;know config_docs;retry jsonb;i intents;BEGIN SELECT*INTO a FROM actor_for(t,'scheduler');IF NOT FOUND THEN RETURN;END IF;FOR f IN SELECT x.*FROM followups x JOIN accounts ac ON ac.id=x.account_ref AND ac.enabled WHERE(x.state='due'OR(x.state='claimed'AND x.claim_until<=n)OR(x.state='retry'AND x.next_attempt<=n))AND x.due_at<=n ORDER BY x.due_at FOR UPDATE OF x SKIP LOCKED LOOP SELECT body INTO retry FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='retry'AND active;IF retry IS NULL OR f.attempts>=COALESCE((retry->>'maxAttempts')::int,0)THEN UPDATE followups x SET state='suppressed',reason=CASE WHEN retry IS NULL THEN'missing_retry'ELSE'retry_exhausted'END WHERE(x.account_ref,x.id)=(f.account_ref,f.id);CONTINUE;END IF;UPDATE followups x SET state='claimed',claim=gen_random_uuid(),claim_until=n+make_interval(secs=>(retry->>'followupClaimSeconds')::int),attempts=attempts+1 WHERE(x.account_ref,x.id)=(f.account_ref,f.id);SELECT*INTO pol FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='sales_policy'AND active;SELECT*INTO know FROM config_docs d WHERE d.account_ref=f.account_ref AND kind='product_knowledge'AND active;IF pol.version IS NULL OR know.version IS NULL THEN UPDATE followups x SET state='retry',reason='missing_config',next_attempt=n+make_interval(secs=>(retry->>'backoffSeconds')::int),claim=NULL,claim_until=NULL WHERE(x.account_ref,x.id)=(f.account_ref,f.id);CONTINUE;END IF;INSERT INTO intents(account_ref,contact_id,conversation_id,source_id,kind,expected_version,policy_version,knowledge_version,body,template_key,provenance)VALUES(f.account_ref,f.contact_id,f.conversation_id,f.id,'followup',f.expected_version,pol.version,know.version,'Synthetic follow-up.',f.template_key,'{"sourceIds":["source-1"],"offerId":"offer-1","claims":["service-count"],"confidence":1.0}')ON CONFLICT(account_ref,conversation_id,source_id,kind)DO UPDATE SET body=intents.body RETURNING*INTO i;UPDATE followups x SET state='intent_created',intent_id=i.id,claim=NULL,claim_until=NULL WHERE(x.account_ref,x.id)=(f.account_ref,f.id);account_ref:=f.account_ref;work_id:=i.id;RETURN NEXT;END LOOP;END$$;

CREATE OR REPLACE FUNCTION claim_handoff(t text,acct text,work uuid,n timestamptz DEFAULT now())RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;h handoffs;cfg jsonb;v conversations;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN RETURN'{"ok":false,"terminal":"denied","reason":"account_disabled"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND THEN RETURN'{"ok":false,"terminal":"denied","reason":"not_found"}';END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;SELECT*INTO v FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF v.lifecycle IN('opted_out','deleted')THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',v.lifecycle);ELSIF cfg IS NULL THEN RETURN'{"ok":false,"terminal":"denied","reason":"missing_config"}';ELSIF h.state IN('acknowledged','suppressed')THEN RETURN jsonb_build_object('ok',false,'terminal','denied','reason','terminal_state','state',h.state);ELSIF h.state='claimed'AND h.claim_until>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"already_claimed"}';ELSIF h.state NOT IN('pending','claimed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_state"}';ELSIF h.attempts>=(cfg->>'maxAttempts')::int THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN'{"ok":false,"terminal":"denied","reason":"retry_exhausted"}';ELSIF h.next_attempt>n THEN RETURN'{"ok":false,"terminal":"denied","reason":"backoff"}';END IF;UPDATE handoffs SET state='claimed',claim=gen_random_uuid(),claim_until=n+make_interval(secs=>(cfg->>'claimSeconds')::int),attempts=attempts+1 WHERE(account_ref,id)=(acct,work)RETURNING*INTO h;RETURN jsonb_build_object('ok',true,'terminal','claimed','account_ref',acct,'work_id',h.id,'claim',h.claim,'queue',h.queue,'deadline',h.deadline);END$$;

CREATE OR REPLACE FUNCTION recheck_handoff(t text,acct text,work uuid,c uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;h handoffs;life text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND OR h.state<>'claimed'OR h.claim<>c OR h.claim_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"claim_mismatch"}';END IF;SELECT lifecycle INTO life FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)OR life='opted_out'OR life='deleted'OR NOT EXISTS(SELECT 1 FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active)THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',CASE WHEN life IN('opted_out','deleted')THEN life WHEN NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN'account_disabled'ELSE'missing_config'END);END IF;RETURN jsonb_build_object('ok',true,'terminal','authorized','account_ref',acct,'work_id',work,'claim',c);END$$;

CREATE OR REPLACE FUNCTION finish_handoff(t text,acct text,work uuid,c uuid,outcome text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;h handoffs;cfg jsonb;life text;BEGIN SELECT*INTO a FROM actor_for(t);IF NOT FOUND OR a.role NOT IN('runtime','scheduler')OR(a.role='runtime'AND a.account_ref<>acct)THEN RETURN'{"ok":false,"terminal":"denied","reason":"wrong_account"}';END IF;SELECT*INTO h FROM handoffs WHERE(account_ref,id)=(acct,work)FOR UPDATE;IF NOT FOUND OR h.state<>'claimed'OR h.claim<>c OR h.claim_until<=now()THEN RETURN'{"ok":false,"terminal":"denied","reason":"claim_mismatch"}';END IF;IF outcome NOT IN('success','retryable','failed')THEN RETURN'{"ok":false,"terminal":"denied","reason":"invalid_outcome"}';END IF;SELECT lifecycle INTO life FROM conversations WHERE(account_ref,id)=(acct,h.conversation_id);IF life IN('opted_out','deleted')OR NOT EXISTS(SELECT 1 FROM accounts WHERE id=acct AND enabled)THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN jsonb_build_object('ok',false,'terminal','denied','reason',CASE WHEN life IN('opted_out','deleted')THEN life ELSE'account_disabled'END);END IF;SELECT body INTO cfg FROM config_docs WHERE account_ref=acct AND kind='handoff'AND active;IF cfg IS NULL THEN UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);RETURN'{"ok":false,"terminal":"denied","reason":"missing_config"}';ELSIF outcome='success'THEN UPDATE handoffs SET state='acknowledged',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);ELSIF outcome='retryable'AND h.attempts<(cfg->>'maxAttempts')::int THEN UPDATE handoffs SET state='pending',next_attempt=now()+make_interval(secs=>(cfg->>'backoffSeconds')::int),claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);ELSE UPDATE handoffs SET state='suppressed',claim=NULL,claim_until=NULL WHERE(account_ref,id)=(acct,work);END IF;RETURN(SELECT jsonb_build_object('ok',true,'terminal',state,'next_attempt',next_attempt)FROM handoffs WHERE(account_ref,id)=(acct,work));END$$;


CREATE OR REPLACE FUNCTION schedule_work(t text,n timestamptz DEFAULT now())RETURNS TABLE(account_ref text,work_id uuid,workflow_id text)LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;BEGIN SELECT*INTO a FROM actor_for(t,'scheduler');IF NOT FOUND THEN RETURN;END IF;PERFORM count(*)FROM schedule_followups(t,n);RETURN QUERY SELECT i.account_ref,i.id,'salesflow-wf-03'FROM intents i JOIN accounts ac ON ac.id=i.account_ref AND ac.enabled WHERE(i.state='pending'OR(i.state='leased'AND i.lease_until<=n))AND(i.next_attempt IS NULL OR i.next_attempt<=n)UNION ALL SELECT h.account_ref,h.id,'salesflow-wf-06'FROM handoffs h JOIN accounts ac ON ac.id=h.account_ref AND ac.enabled WHERE(h.state='pending'OR(h.state='claimed'AND h.claim_until<=n))AND(h.next_attempt IS NULL OR h.next_attempt<=n)ORDER BY 1,2;END$$;

CREATE OR REPLACE FUNCTION callback(t text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$DECLARE a record;i intents;e provider_events;pt timestamptz;h text;rank_old int;rank_new int;BEGIN SELECT*INTO a FROM actor_for(t,'runtime');IF NOT FOUND OR p->>'account_ref'<>a.account_ref THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;IF COALESCE(p->>'event_id','')=''OR COALESCE(p->>'provider_id','')=''OR COALESCE(p->>'status','')NOT IN('accepted','sent','delivered','read','failed')THEN RETURN'{"ok":false,"reason":"invalid"}';END IF;BEGIN pt:=(p->>'provider_time')::timestamptz;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid"}';END;IF pt>now()+interval'5 min'THEN RETURN'{"ok":false,"reason":"future"}';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(a.account_ref||':'||(p->>'event_id'),0));SELECT x.*INTO i FROM intents x JOIN conversations v ON(v.account_ref,v.id)=(x.account_ref,x.conversation_id)WHERE(x.account_ref,x.provider_id)=(a.account_ref,p->>'provider_id')AND v.lifecycle<>'deleted'FOR UPDATE OF x;IF NOT FOUND THEN RETURN'{"ok":false,"reason":"provider_mismatch"}';END IF;h:=encode(digest(p::text,'sha256'),'hex');SELECT*INTO e FROM provider_events WHERE(account_ref,event_id)=(a.account_ref,p->>'event_id');IF FOUND THEN RETURN CASE WHEN e.payload_hash=h THEN jsonb_build_object('ok',true,'created',false,'status',i.provider_status)ELSE'{"ok":false,"reason":"idempotency_conflict"}'::jsonb END;END IF;INSERT INTO provider_events VALUES(a.account_ref,p->>'event_id',i.id,p->>'provider_id',p->>'status',pt,h);rank_old:=array_position(ARRAY['accepted','sent','delivered','read'],i.provider_status);rank_new:=array_position(ARRAY['accepted','sent','delivered','read'],p->>'status');IF (p->>'status'='failed'AND COALESCE(rank_old,0)<3 AND(i.provider_time IS NULL OR pt>=i.provider_time))OR(p->>'status'<>'failed'AND(i.provider_time IS NULL OR(pt>=i.provider_time AND rank_new>=COALESCE(rank_old,0))))THEN UPDATE intents SET provider_status=p->>'status',provider_time=pt WHERE(account_ref,id)=(a.account_ref,i.id)RETURNING*INTO i;END IF;RETURN jsonb_build_object('ok',true,'created',true,'status',i.provider_status);END$$;

CREATE OR REPLACE FUNCTION operations(t text,acct text,p jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salesflow,public AS $$
DECLARE a record;c uuid;r uuid;n int;mh text;ret jsonb;rs jsonb;previous text;
BEGIN
 SELECT*INTO a FROM actor_for(t,'operator');IF NOT FOUND OR(acct IS NOT NULL AND a.account_ref<>acct)THEN RETURN'{"ok":false,"reason":"wrong_account"}';END IF;IF acct IS NULL THEN acct:=a.account_ref;END IF;
 IF jsonb_typeof(p)<>'object'OR COALESCE(p->>'action','')=''THEN RETURN'{"ok":false,"reason":"invalid_input"}';
 ELSIF p->>'action'='evidence'THEN SELECT body INTO ret FROM config_docs WHERE account_ref=acct AND kind='retention'AND active;IF ret IS NULL THEN RETURN'{"ok":false,"reason":"missing_retention"}';END IF;RETURN jsonb_build_object('ok',true,'terminal','evidence','account_ref',acct,'events',(SELECT count(*)FROM audit_events WHERE account_ref=acct),'retentionVersion',ret->>'version','auditDays',(ret->>'auditDays')::int,'messageDays',(ret->>'messageDays')::int,'activeRelease',(SELECT release_id FROM release_pointers WHERE account_ref=acct));
 ELSIF p->>'action'='delete'THEN
  BEGIN c:=(p->>'contact_id')::uuid;EXCEPTION WHEN OTHERS THEN RETURN'{"ok":false,"reason":"invalid_input"}';END;IF NOT EXISTS(SELECT 1 FROM contacts WHERE(account_ref,id)=(acct,c))THEN RETURN'{"ok":false,"reason":"not_found"}';END IF;
  INSERT INTO deletion_requests(account_ref,contact_id)VALUES(acct,c)RETURNING id INTO r;INSERT INTO deletion_targets SELECT acct,r,'inbound_message',id::text,'pending'FROM inbound_messages WHERE account_ref=acct AND conversation_id IN(SELECT id FROM conversations WHERE account_ref=acct AND contact_id=c)UNION ALL SELECT acct,r,'intent',id::text,'pending'FROM intents WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'followup',id::text,'pending'FROM followups WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'handoff',id::text,'pending'FROM handoffs WHERE account_ref=acct AND contact_id=c UNION ALL SELECT acct,r,'consent',occurred_at::text,'pending'FROM consent_events WHERE(account_ref,contact_id)=(acct,c)UNION ALL SELECT acct,r,'contact',c::text,'pending';
  PERFORM set_config('salesflow.deletion_mode','on',true);UPDATE provider_events e SET provider_id='deleted-'||e.intent_id::text,payload_hash=encode(digest('[deleted]','sha256'),'hex')WHERE e.account_ref=acct AND e.intent_id IN(SELECT id FROM intents WHERE account_ref=acct AND contact_id=c);UPDATE conversations SET lifecycle='deleted'WHERE(account_ref,contact_id)=(acct,c);UPDATE intents SET state='suppressed',reason='deleted',body='[deleted]',provenance='{}',provider_id=CASE WHEN provider_id IS NULL THEN NULL ELSE'deleted-'||id::text END,lease=NULL,lease_until=NULL WHERE account_ref=acct AND contact_id=c;UPDATE handoffs SET state='suppressed',evidence='{}',claim=NULL,claim_until=NULL WHERE account_ref=acct AND contact_id=c;UPDATE followups SET state='suppressed',reason='deleted',claim=NULL,claim_until=NULL WHERE account_ref=acct AND contact_id=c;UPDATE inbound_messages SET body='[deleted]',body_hash=encode(digest('[deleted]','sha256'),'hex'),contact_ref='[deleted]'WHERE account_ref=acct AND conversation_id IN(SELECT id FROM conversations WHERE account_ref=acct AND contact_id=c);UPDATE consent_events SET evidence='[deleted]'WHERE(account_ref,contact_id)=(acct,c);UPDATE contacts SET external_ref='deleted-'||id::text WHERE(account_ref,id)=(acct,c);UPDATE deletion_targets SET state='completed'WHERE(account_ref,request_id)=(acct,r);UPDATE deletion_requests SET state='completed',completed_at=now()WHERE(account_ref,id)=(acct,r);SELECT count(*)INTO n FROM deletion_targets WHERE(account_ref,request_id)=(acct,r);RETURN jsonb_build_object('ok',true,'terminal','deleted','request_id',r,'targets',n,'completed',true);
 ELSIF p->>'action'='release'THEN
  IF COALESCE(p->>'release_id','')=''OR jsonb_typeof(p->'manifest')<>'object'OR NOT(p->'manifest'?&ARRAY['version','policyVersion','knowledgeVersion','images','configFiles','workflowFiles','workflowHashes','inputHashes'])OR COALESCE(p->>'manifest_hash','')!~'^[0-9a-f]{64}$'THEN RETURN'{"ok":false,"reason":"invalid_input"}';END IF;
  mh:=encode(digest((p->'manifest')::text,'sha256'),'hex');SELECT body INTO rs FROM config_docs WHERE account_ref=acct AND kind='release_set'AND active;IF mh<>p->>'manifest_hash'OR rs IS NULL OR rs->>'reviewedManifestHash'<>mh OR rs->>'manifestVersion'<>p#>>'{manifest,version}'OR rs->>'policyVersion'<>p#>>'{manifest,policyVersion}'OR rs->>'knowledgeVersion'<>p#>>'{manifest,knowledgeVersion}'THEN RETURN'{"ok":false,"reason":"manifest_mismatch"}';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('release:'||acct,0));IF EXISTS(SELECT 1 FROM releases WHERE(account_ref,id)=(acct,p->>'release_id'))THEN RETURN'{"ok":false,"reason":"release_exists"}';END IF;SELECT release_id INTO previous FROM release_pointers WHERE account_ref=acct FOR UPDATE;INSERT INTO releases(account_ref,id,manifest_hash,manifest,active)VALUES(acct,p->>'release_id',mh,p->'manifest',false);INSERT INTO release_pointers VALUES(acct,p->>'release_id',mh)ON CONFLICT(account_ref)DO UPDATE SET release_id=EXCLUDED.release_id,manifest_hash=EXCLUDED.manifest_hash;INSERT INTO audit_events(account_ref,event,reason,actor,details)VALUES(acct,'release_activated',p->>'release_id',a.actor,jsonb_build_object('manifest_hash',mh));RETURN jsonb_build_object('ok',true,'terminal','released','previous_release',previous);
 END IF;RETURN'{"ok":false,"reason":"invalid_action"}';
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'reason','invalid_input');END$$;

REVOKE ALL ON SCHEMA salesflow FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA salesflow FROM PUBLIC,salesflow_runtime;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA salesflow FROM PUBLIC,salesflow_runtime;
GRANT USAGE ON SCHEMA salesflow TO salesflow_runtime;
GRANT EXECUTE ON FUNCTION ingest(text,jsonb),complete_turn(text,text,uuid),set_consent(text,text,uuid,text,text),claim_dispatch(text,text,uuid,timestamptz),recheck_dispatch(text,text,uuid,uuid),finish_dispatch(text,text,uuid,uuid,text),callback(text,jsonb),schedule_followups(text,timestamptz),schedule_work(text,timestamptz),claim_handoff(text,text,uuid,timestamptz),recheck_handoff(text,text,uuid,uuid),finish_handoff(text,text,uuid,uuid,text),operations(text,text,jsonb) TO salesflow_runtime;
ALTER DEFAULT PRIVILEGES FOR ROLE salesflow_owner IN SCHEMA salesflow REVOKE ALL ON TABLES FROM PUBLIC;
RESET ROLE;
